------------ import ------------
local CanvasGroup = CS.UnityEngine.CanvasGroup
local UIEventProxy = CS.Engine.UI.UIEventProxy
------------ import ------------

------------ define ------------
local NUM_EMOJI_PRE_PAGE = 6
local STRING_PATH_MSG_CELL = "EmojiGroupCell"
local LUA_PATH_MSG_CELL = "Game.UI.UIBattling.BattlePVP.UIBattlingPVPMsgCell"
------------ define ------------

---@class UIBattlingPVPMsgRoot
---@field DotCell                       	UnityEngine.RectTransform
---@field PageListView                  	UnityEngine.RectTransform
---@field EmptyBg                       	UnityEngine.RectTransform
---@field EmojiListView                 	SuperScrollView.LoopGridView
---@field RT_PanelBg                        UnityEngine.RectTransform
local UIBattlingPVPMsgRoot = Class('UIBattlingPVPMsgRoot')

------------ lifeCycle ------------
function UIBattlingPVPMsgRoot:__init()
    self.cgPanel = nil
    self.listEmojiVoGroup = {}
end

function UIBattlingPVPMsgRoot:__delete()
    self.cgPanel = nil
    self.listEmojiVoGroup = nil
    self.listDotCells = nil
end

function UIBattlingPVPMsgRoot:Awake()
    self.cgPanel = self.controller.gameObject:GetComponent(typeof(CanvasGroup))
    UIEventProxy.Create(self.EmptyBg.gameObject).onPointerClick = function()
        self:SetPanelShowState(false)
    end
    self.EmojiListView.mOnSnapItemFinished = Bind(self, self.UpdateDotCellsStatue)
end

function UIBattlingPVPMsgRoot:Start()
    self:InitEmojiData()
    self:InitDotCellsList()
    self:RefreshScrollView()
end

function UIBattlingPVPMsgRoot:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
------------ lifeCycle ------------

------------ init ------------

function UIBattlingPVPMsgRoot:InitEmojiData()
    ---@type SettingMgr
    local settingMgr = SettingMgr:GetInstance()
    ---@type BaseSetting
    local setting = settingMgr:GetSetting(AutoIds.IdSetting2767, "GoodsEmojiVo")
    local allEmojiVo = setting:GetAll()

    -- 检查玩家背包里有没有指定的表情，如果有设置成解锁状态，如果没有设置成锁定状态
    local emojiDataList = {}
    local unlockList = {}
    local lockList = {}
    for k, v in ipairs(allEmojiVo) do
        local emojiData = {
            vo = v,
            unlock = GoodsUtils.GetThingNo(v.id) > 0
        }
        if emojiData.unlock then
            table.insert(unlockList, emojiData)
        else
            table.insert(lockList, emojiData)
        end
    end
    -- 已经解锁的表情排在前面，未解锁的表情排在后面
    table.link(emojiDataList, unlockList)
    table.link(emojiDataList, lockList)

    -- 把表情数据按页保存
    self.listEmojiVoGroup = {}
    for i = 1, #emojiDataList do
        local curEmojiData = emojiDataList[i]
        local pathInGroupIndex = math.ceil(i / NUM_EMOJI_PRE_PAGE)
        if isNull(self.listEmojiVoGroup[pathInGroupIndex]) then
            self.listEmojiVoGroup[pathInGroupIndex] = {}
        end
        table.insert(self.listEmojiVoGroup[pathInGroupIndex], curEmojiData)
    end
end

function UIBattlingPVPMsgRoot:InitDotCellsList()
    self.listDotCells = {}
    local KTool = CS.Engine.Lib.KTool
    local dotCellsCount = #self.listEmojiVoGroup
    for i = 1, dotCellsCount do
        local goDotCell = KTool.Instantiate(self.PageListView.gameObject, self.DotCell.gameObject, false)
        if not IsNull(goDotCell) then
            KTool.SetActive(goDotCell, true)
            local siDotCell = KTool.GetOrAddComponent(goDotCell, typeof(CS.Game.Native.Common.UISwitchImage))
            if not IsNull(siDotCell) then
                table.insert(self.listDotCells, siDotCell)
            end
        end
    end
end

------------ init ------------

function UIBattlingPVPMsgRoot:ShowPanel()
    self:SetPanelShowState(true)
end

function UIBattlingPVPMsgRoot:SetPanelShowState(isShow)
    if not IsNull(self.cgPanel) then
        self.cgPanel.alpha = isShow and 1 or 0
        self.cgPanel.interactable = isShow
        self.cgPanel.blocksRaycasts = isShow
    end
end

--- 设置表情选择界面在左还是在右
---@param type integer (0:左，1:右)
function UIBattlingPVPMsgRoot:SetPanelPos(type)
    if type == 0 then
        self.RT_PanelBg.anchorMin = Vector2.New(0,0)
        self.RT_PanelBg.anchorMax = Vector2.New(0,0)
        self.RT_PanelBg.anchoredPosition = Vector3.New(356, 168)
    elseif type == 1 then
        self.RT_PanelBg.anchorMin = Vector2.New(1,0)
        self.RT_PanelBg.anchorMax = Vector2.New(1,0)
        self.RT_PanelBg.anchoredPosition = Vector3.New(-760, 168)
    end
end

function UIBattlingPVPMsgRoot:UpdateDotCellsStatue(list, item)
    local indexInList = item.ItemIndex + 1
    for i, cell in ipairs(self.listDotCells) do
        cell.Status = (indexInList == i) and 1 or 2
        cell:Reset()
    end
end

function UIBattlingPVPMsgRoot:RefreshScrollView()
    if self.EmojiListView.IsListViewInit then
        GameUtils.ReloadData(self.EmojiListView, #self.listEmojiVoGroup)
    else
        self.EmojiListView:InitGridView(#self.listEmojiVoGroup, Bind(self, self.OnGetItemByIndex))
    end
end

function UIBattlingPVPMsgRoot:OnGetItemByIndex(gridView, index)
    if index < 0 then return end
    local emojiDataList = self.listEmojiVoGroup[index + 1]
    local cell = gridView:NewListViewItem(STRING_PATH_MSG_CELL)
    if cell then
        local cellLB = GetLuaBehaviour(cell.gameObject, LUA_PATH_MSG_CELL)
        if cellLB then
            if isNull(cellLB.Env) then cellLB:Init() end
            local ltMsgCell = cellLB.Env
            ltMsgCell:SetCellEmoji(emojiDataList)
        end
    end
    return cell
end

return UIBattlingPVPMsgRoot